1	package server
2	
3	import (
4		"math"
5		"net/http"
6		"net/url"
7		"sort"
8		"strconv"
9		"strings"
10		"time"
11	)
12	
13	const metricRangePath = "/api/v1/metric-range"
14	
15	const (
16		// metricRetention is how long accepted samples stay queryable and how far
17		// back from the receive instant a write timestamp may reach.
18		metricRetention = 24 * time.Hour
19		// maxFutureSkew is how far ahead of the receive instant a write timestamp
20		// may lie.
21		maxFutureSkew = 5 * time.Minute
22	
23		maxRangeStepSeconds = 3600
24		maxRangeWindows     = 10000
25	)
26	
27	// historyPoint is one accepted sample, kept per series in commit order.
28	type historyPoint struct {
29		ts    time.Time
30		value float64
31	}
32	
33	type rangePointOutput struct {
34		Timestamp string         `json:"timestamp"`
35		Value     *float64       `json:"value,omitempty"`
36		Count     *int64         `json:"count,omitempty"`
37		Sum       *float64       `json:"sum,omitempty"`
38		Buckets   []bucketOutput `json:"buckets,omitempty"`
39	}
40	
41	type rangeSeriesOutput struct {
42		Name   string             `json:"name"`
43		Type   string             `json:"type"`
44		Labels map[string]string  `json:"labels"`
45		Points []rangePointOutput `json:"points"`
46	}
47	
48	// rangeQuery aggregates retained history into the half-open windows
49	// [start+k*step, start+(k+1)*step) that cover [start, end). Samples older
50	// than now-metricRetention are treated as evicted. ok is false when an
51	// aggregation overflows to a non-finite number; no partial result is
52	// returned in that case.
53	func (s *metricStore) rangeQuery(name string, selector map[string]string, start, end time.Time, step time.Duration, now time.Time) (out []rangeSeriesOutput, ok bool) {
54		s.mu.RLock()
55		defer s.mu.RUnlock()
56	
57		cutoff := now.Add(-metricRetention)
58		matched := make([]*series, 0)
59		for _, cur := range s.series {
60			if cur.name != name {
61				continue
62			}
63			fits := true
64			for k, v := range selector {
65				got, ok := cur.labels[k]
66				if !ok || got != v {
67					fits = false
68					break
69				}
70			}
71			if fits {
72				matched = append(matched, cur)
73			}
74		}
75		sort.Slice(matched, func(i, j int) bool {
76			return compareLabels(matched[i].labels, matched[j].labels) < 0
77		})
78	
79		out = make([]rangeSeriesOutput, 0, len(matched))
80		for _, cur := range matched {
81			points, finite := aggregateWindows(cur, start, end, step, cutoff)
82			if !finite {
83				return nil, false
84			}
85			if len(points) == 0 {
86				continue // empty windows produce no points; point-less series are omitted
87			}
88			out = append(out, rangeSeriesOutput{
89				Name:   cur.name,
90				Type:   cur.typ,
91				Labels: copyLabels(cur.labels),
92				Points: points,
93			})
94		}
95		return out, true
96	}
97	
98	// aggregateWindows builds the points of one series. cur.history is in commit
99	// order, which is also the tie-break order for gauge observations that share
100	// a timestamp.
101	func aggregateWindows(cur *series, start, end time.Time, step time.Duration, cutoff time.Time) ([]rangePointOutput, bool) {
102		inRange := func(ts time.Time) bool {
103			return !ts.Before(cutoff) && !ts.Before(start) && ts.Before(end)
104		}
105		windowOf := func(ts time.Time) int {
106			return int(ts.Sub(start) / step)
107		}
108		windowStart := func(k int) string {
109			return start.Add(time.Duration(k) * step).UTC().Format(time.RFC3339Nano)
110		}
111	
112		switch cur.typ {
113		case "counter":
114			sums := make(map[int]float64)
115			for _, p := range cur.history {
116				if inRange(p.ts) {
117					sums[windowOf(p.ts)] += p.value
118				}
119			}
120			points := make([]rangePointOutput, 0, len(sums))
121			for _, k := range sortedWindowKeys(sums) {
122				v := sums[k]
123				if math.IsNaN(v) || math.IsInf(v, 0) {
124					return nil, false
125				}
126				points = append(points, rangePointOutput{Timestamp: windowStart(k), Value: &v})
127			}
128			return points, true
129	
130		case "gauge":
131			best := make(map[int]historyPoint)
132			for _, p := range cur.history {
133				if !inRange(p.ts) {
134					continue
135				}
136				k := windowOf(p.ts)
137				if cur2, ok := best[k]; !ok || !p.ts.Before(cur2.ts) {
138					best[k] = p // equal timestamps: the later commit wins
139				}
140			}
141			points := make([]rangePointOutput, 0, len(best))
142			for _, k := range sortedWindowKeys(best) {
143				v := best[k].value
144				points = append(points, rangePointOutput{Timestamp: windowStart(k), Value: &v})
145			}
146			return points, true
147	
148		case "histogram":
149			type histAgg struct {
150				count   int64
151				sum     float64
152				buckets []int64
153			}
154			aggs := make(map[int]*histAgg)
155			for _, p := range cur.history {
156				if !inRange(p.ts) {
157					continue
158				}
159				k := windowOf(p.ts)
160				a, ok := aggs[k]
161				if !ok {
162					a = &histAgg{buckets: make([]int64, len(cur.bucketBounds))}
163					aggs[k] = a
164				}
165				a.count++
166				a.sum += p.value
167				for i, bound := range cur.bucketBounds {
168					if p.value <= bound {
169						a.buckets[i]++
170					}
171				}
172			}
173			points := make([]rangePointOutput, 0, len(aggs))
174			for _, k := range sortedWindowKeys(aggs) {
175				a := aggs[k]
176				if math.IsNaN(a.sum) || math.IsInf(a.sum, 0) {
177					return nil, false
178				}
179				count, sum := a.count, a.sum
180				buckets := make([]bucketOutput, len(cur.bucketBounds))
181				for i, bound := range cur.bucketBounds {
182					buckets[i] = bucketOutput{LE: bound, Count: a.buckets[i]}
183				}
184				points = append(points, rangePointOutput{
185					Timestamp: windowStart(k),
186					Count:     &count,
187					Sum:       &sum,
188					Buckets:   buckets,
189				})
190			}
191			return points, true
192		}
193		return nil, true
194	}
195	
196	func sortedWindowKeys[V any](m map[int]V) []int {
197		keys := make([]int, 0, len(m))
198		for k := range m {
199			keys = append(keys, k)
200		}
201		sort.Ints(keys)
202		return keys
203	}
204	
205	// parseStep validates the step parameter: integer seconds in [1, 3600].
206	func parseStep(raw string) (time.Duration, bool) {
207		if raw == "" {
208			return 0, false
209		}
210		for i := 0; i < len(raw); i++ {
211			if raw[i] < '0' || raw[i] > '9' {
212				return 0, false
213			}
214		}
215		n, err := strconv.Atoi(raw)
216		if err != nil || n < 1 || n > maxRangeStepSeconds {
217			return 0, false
218		}
219		return time.Duration(n) * time.Second, true
220	}
221	
222	func registerMetricRangeHandler(mux *http.ServeMux) {
223		mux.HandleFunc(metricRangePath, func(w http.ResponseWriter, r *http.Request) {
224			if r.Method != http.MethodGet {
225				w.Header().Set("Allow", http.MethodGet)
226				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
227				return
228			}
229			invalid := func() {
230				writeAPIError(w, "invalid_metric_range", http.StatusBadRequest)
231			}
232	
233			values, err := url.ParseQuery(r.URL.RawQuery)
234			if err != nil {
235				invalid()
236				return
237			}
238	
239			// Only name, label.<key>, start, end and step are accepted; every
240			// parameter key may appear at most once.
241			selector := make(map[string]string)
242			var name, startRaw, endRaw, stepRaw string
243			var haveName, haveStart, haveEnd, haveStep bool
244			for key, vals := range values {
245				if len(vals) != 1 {
246					invalid()
247					return
248				}
249				v := vals[0]
250				switch {
251				case key == "name":
252					if !identPattern.MatchString(v) {
253						invalid()
254						return
255					}
256					name, haveName = v, true
257				case key == "start":
258					startRaw, haveStart = v, true
259				case key == "end":
260					endRaw, haveEnd = v, true
261				case key == "step":
262					stepRaw, haveStep = v, true
263				case strings.HasPrefix(key, "label."):
264					labelKey := strings.TrimPrefix(key, "label.")
265					if !identPattern.MatchString(labelKey) {
266						invalid()
267						return
268					}
269					selector[labelKey] = v
270				default:
271					invalid()
272					return
273				}
274			}
275			if !haveName || !haveStart || !haveEnd || !haveStep {
276				invalid()
277				return
278			}
279	
280			start, err := time.Parse(time.RFC3339Nano, startRaw)
281			if err != nil {
282				invalid()
283				return
284			}
285			end, err := time.Parse(time.RFC3339Nano, endRaw)
286			if err != nil {
287				invalid()
288				return
289			}
290			if !start.Before(end) {
291				invalid()
292				return
293			}
294			step, ok := parseStep(stepRaw)
295			if !ok {
296				invalid()
297				return
298			}
299	
300			// Half-open windows are cut consecutively from start; the last one
301			// may extend past end but samples are only counted while ts < end.
302			span := end.Sub(start)
303			windows := int64(span) / int64(step)
304			if int64(span)%int64(step) != 0 {
305				windows++
306			}
307			if windows > maxRangeWindows {
308				invalid()
309				return
310			}
311	
312			out, finite := tenantStore(r).rangeQuery(name, selector, start, end, step, time.Now())
313			if !finite {
314				writeAPIError(w, "invalid_metric_range_data", http.StatusUnprocessableEntity)
315				return
316			}
317			writeJSON(w, http.StatusOK, map[string]any{"series": out})
318		})
319	}
