1	package server
2	
3	import (
4		"encoding/json"
5		"math"
6		"net/http"
7		"net/url"
8		"sort"
9	)
10	
11	const queryPath = "/api/v1/query"
12	
13	// ---- expression AST --------------------------------------------------------
14	
15	// queryExpr is one parsed expression: either a bare selector (aggregate ==
16	// "") or one of sum/avg/min/max, optionally grouped by non-empty by labels.
17	type queryExpr struct {
18		aggregate string
19		by        []string
20		metric    string
21		selector  map[string]string
22	}
23	
24	var queryAggregates = map[string]bool{
25		"sum": true,
26		"avg": true,
27		"min": true,
28		"max": true,
29	}
30	
31	// ---- expression parser -----------------------------------------------------
32	
33	type exprParser struct {
34		s string
35		p int
36	}
37	
38	// parseQueryExpr parses the single expression accepted by GET /api/v1/query.
39	// Whitespace is ASCII only and may surround any punctuation or keyword. The
40	// grammar:
41	//
42	//	expr        := selector | aggregation
43	//	aggregation := ident ("by" "(" ident ("," ident)* ")")? "(" selector ")"
44	//	selector    := ident "{" (ident "=" jsonString ("," ident "=" jsonString)*)? "}"
45	//
46	// The aggregation identifier must be one of sum/avg/min/max. Duplicate
47	// matchers or grouping labels, nested aggregations, unknown functions and any
48	// trailing input are rejected.
49	func parseQueryExpr(in string) (*queryExpr, bool) {
50		p := &exprParser{s: in}
51		p.skipSpaces()
52	
53		word, ok := p.parseIdent()
54		if !ok {
55			return nil, false
56		}
57		p.skipSpaces()
58	
59		e := &queryExpr{}
60		// A function name introduces an aggregation only when it is followed by a
61		// call ("(" or a by clause); followed by "{" it is simply a metric named
62		// like the keyword (metric writes impose no such reservation).
63		if queryAggregates[word] && (p.next() == '(' || p.hasIdent("by")) {
64			e.aggregate = word
65			if p.hasIdent("by") {
66				p.p += 2
67				p.skipSpaces()
68				if !p.expect('(') {
69					return nil, false
70				}
71				seen := make(map[string]bool)
72				for {
73					p.skipSpaces()
74					label, ok := p.parseIdent()
75					if !ok {
76						return nil, false
77					}
78					if seen[label] {
79						return nil, false
80					}
81					seen[label] = true
82					e.by = append(e.by, label)
83					p.skipSpaces()
84					switch p.next() {
85					case ',':
86						p.p++
87						continue
88					case ')':
89						p.p++
90					default:
91						return nil, false
92					}
93					break
94				}
95				p.skipSpaces()
96			}
97			if !p.expect('(') {
98				return nil, false
99			}
100			p.skipSpaces()
101			if !p.parseSelectorInto(e) {
102				return nil, false
103			}
