126	// parseSelectorInto parses metric "{" matcher-list "}" starting at the metric
127	// name; used for selectors nested inside an aggregation call.
128	func (p *exprParser) parseSelectorInto(e *queryExpr) bool {
129		name, ok := p.parseIdent()
