141	// parseMatcherListInto parses matcher-list "}" with the opening "{" consumed.
142	func (p *exprParser) parseMatcherListInto(e *queryExpr) bool {
143		e.selector = make(map[string]string)
144		p.skipSpaces()
145		if p.next() == '}' {
146			p.p++
147			return true
148		}
149		for {
150			p.skipSpaces()
