160				return false
161			}
162			p.skipSpaces()
163			value, ok := p.parseJSONString()
164			if !ok {
165				return false
166			}
167			e.selector[key] = value
168			p.skipSpaces()
169			switch p.next() {
170			case ',':
171				p.p++
172				continue
173			case '}':
174				p.p++
175				return true
176			default:
177				return false
178			}
179		}
