283	// store snapshot. Only current values of matching counter and gauge series
284	// participate; histograms are ignored. The third result is false when a
285	// selected value or an aggregate is not a finite number.
286	func (s *metricStore) executeQuery(e *queryExpr) ([]querySample, bool) {
287		s.mu.RLock()
288		defer s.mu.RUnlock()
289	
290		matched := make([]matchedSeries, 0)
291		for _, cur := range s.series {
292			if cur.typ != "counter" && cur.typ != "gauge" {
293				continue
294			}
295			if cur.name != e.metric {
