315		if e.aggregate == "" {
316			out := make([]querySample, 0, len(matched))
317			for _, m := range matched {
318				out = append(out, querySample{Labels: m.labels, Value: m.value})
319			}
320			sort.Slice(out, func(i, j int) bool {
