334			projected := make(map[string]string, len(e.by))
335			for _, label := range e.by {
336				if v, ok := m.labels[label]; ok {
337					projected[label] = v
338				}
339			}
340			key := seriesKey("", projected)
341			g, seen := groups[key]
342			if !seen {
343				g = &groupAcc{labels: projected, value: m.value, count: 1}
344				groups[key] = g
345				order = append(order, key)
346				continue
347			}
348			g.count++
349			switch e.aggregate {
350			case "sum", "avg":
351				g.value += m.value
352			case "min":
