1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21		"time"
22	)
23	
24	// Version is the baseline release identifier.
25	const Version = "0.1.0"
26	
27	const metricsPath = "/api/v1/metrics"
28	
29	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
30	
31	type health struct {
32		Status  string `json:"status"`
33		Service string `json:"service"`
34		Version string `json:"version"`
35	}
36	
37	// series is one uniquely identified time series: name + full label set.
38	type series struct {
39		name   string
40		typ    string
41		labels map[string]string
42	
43		// counter/gauge state
44		value float64
45	
46		// histogram state
47		bucketBounds []float64 // strictly increasing, fixed at first write
48		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
49		count        int64
50		sum          float64
51	
52		// history holds accepted samples in commit order for range queries.
53		// Entries older than the retention window are ignored at query time;
54		// evicting them never touches the cumulative state above.
55		history []historyPoint
56	}
57	
58	type metricStore struct {
59		mu     sync.RWMutex
60		series map[string]*series
61	
62		// alert rules keyed by rule id; guarded by mu so rule replacement and
63		// alert evaluation are atomic with metric commits.
64		rules map[string]*alertRule
65	
66		// silences keyed by silence id; same lock so alert evaluation reads
67		// metrics, rules and silences from one consistent snapshot.
68		silences map[string]*silence
69	
70		// inhibit rules keyed by rule id; same lock so alert evaluation also
71		// reads inhibit rules from the same consistent snapshot.
72		inhibitions map[string]*inhibitRule
73	
74		// notification routes keyed by route id; same lock so the notification
75		// plan reads routes from the same snapshot as alert evaluation.
76		notificationRoutes map[string]*notificationRoute
77	
78		// SLO definitions keyed by SLO id; same lock so status evaluation reads
79		// definitions and counters from one consistent snapshot.
80		slos map[string]*sloDefinition
81	
82		// Log entries keyed by entry id; same lock so log commits and retrieval
83		// read one consistent snapshot. logOrder is the submission-order FIFO
84		// of ids used for eviction; logSeq is the commit sequence that anchors
85		// paginated read snapshots.
86		logs     map[string]*logEntry
87		logOrder []string
88		logSeq   int64
89	
90		// Spans keyed by tenant-unique "trace_id\x00span_id"; same lock so span
91		// commits and trace reads share the logs snapshot they join against.
92		spans map[string]*span
93	}
94	
95	func newMetricStore() *metricStore {
96		return &metricStore{
97			series:             make(map[string]*series),
98			rules:              make(map[string]*alertRule),
99			silences:           make(map[string]*silence),
100			inhibitions:        make(map[string]*inhibitRule),
101			notificationRoutes: make(map[string]*notificationRoute),
102			slos:               make(map[string]*sloDefinition),
103			logs:               make(map[string]*logEntry),
104			spans:              make(map[string]*span),
105		}
106	}
107	
108	// validatedSample is a sample that passed all format and value checks.
109	type validatedSample struct {
110		key     string
111		name    string
112		typ     string
113		labels  map[string]string
114		value   float64
115		buckets []float64 // non-nil for histograms
116		ts      time.Time
117	}
118	
119	// checkAndApply validates the batch against the current state (and against
120	// itself) and then commits it in array order. A false result signals a type or
121	// bucket-boundary conflict; in that case no state is mutated.
122	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
123		s.mu.Lock()
124		defer s.mu.Unlock()
125	
126		// First pass: conflict detection against committed state and earlier
127		// samples in the same batch.
128		resolved := make(map[string]*series, len(batch))
129		for _, sm := range batch {
130			existing, ok := s.series[sm.key]
131			if !ok {
132				if shadow, seen := resolved[sm.key]; seen {
133					existing, ok = shadow, true
134				}
135			}
136			if ok {
137				if existing.typ != sm.typ {
138					return false
139				}
140				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
141					return false
142				}
143				resolved[sm.key] = existing
144				continue
145			}
146			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
147		}
148	
149		// Second pass: commit in order.
150		for _, sm := range batch {
151			cur, ok := s.series[sm.key]
152			if !ok {
153				cur = &series{
154					name:         sm.name,
155					typ:          sm.typ,
156					labels:       sm.labels,
157					bucketBounds: append([]float64(nil), sm.buckets...),
158				}
159				if sm.typ == "histogram" {
160					cur.bucketCounts = make([]int64, len(sm.buckets))
161				}
162				s.series[sm.key] = cur
163			}
164			switch sm.typ {
165			case "counter":
166				cur.value += sm.value
167			case "gauge":
168				cur.value = sm.value
169			case "histogram":
170				cur.count++
171				cur.sum += sm.value
172				for i, bound := range cur.bucketBounds {
173					if sm.value <= bound {
174						cur.bucketCounts[i]++
175					}
176				}
177			}
178			cur.history = append(cur.history, historyPoint{ts: sm.ts, value: sm.value})
179		}
180		return true
181	}
182	
183	type seriesOutput struct {
184		Name    string            `json:"name"`
185		Type    string            `json:"type"`
186		Labels  map[string]string `json:"labels"`
187		Value   *float64          `json:"value,omitempty"`
188		Count   *int64            `json:"count,omitempty"`
189		Sum     *float64          `json:"sum,omitempty"`
190		Buckets []bucketOutput    `json:"buckets,omitempty"`
191	}
192	
193	type bucketOutput struct {
194		LE    float64 `json:"le"`
195		Count int64   `json:"count"`
196	}
197	
198	// query returns matching series as ready-to-encode outputs. A series matches
199	// when its name equals name exactly and it contains every selector label.
200	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
201		s.mu.RLock()
202		defer s.mu.RUnlock()
203	
204		out := make([]seriesOutput, 0)
205		for _, cur := range s.series {
206			if cur.name != name {
207				continue
208			}
209			matched := true
210			for k, v := range selector {
211				got, ok := cur.labels[k]
212				if !ok || got != v {
213					matched = false
214					break
215				}
216			}
217			if !matched {
218				continue
219			}
220			item := seriesOutput{
221				Name:   cur.name,
222				Type:   cur.typ,
223				Labels: copyLabels(cur.labels),
224			}
225			switch cur.typ {
226			case "counter", "gauge":
227				v := cur.value
228				item.Value = &v
229			case "histogram":
230				c, sum := cur.count, cur.sum
231				item.Count = &c
232				item.Sum = &sum
233				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
234				for i, bound := range cur.bucketBounds {
235					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
236				}
237			}
238			out = append(out, item)
239		}
240	
241		sort.Slice(out, func(i, j int) bool {
242			return compareLabels(out[i].Labels, out[j].Labels) < 0
243		})
244		return out
245	}
246	
247	// compareLabels imposes a normalized lexicographic order on full label sets:
248	// keys are sorted, then (key, value) pairs are compared element-wise, and a
249	// shorter pair list sorts first when it is a prefix of a longer one.
250	func compareLabels(a, b map[string]string) int {
251		ka := sortedKeys(a)
252		kb := sortedKeys(b)
253		n := len(ka)
254		if len(kb) < n {
255			n = len(kb)
256		}
257		for i := 0; i < n; i++ {
258			if ka[i] != kb[i] {
259				return strings.Compare(ka[i], kb[i])
260			}
261			if a[ka[i]] != b[kb[i]] {
262				return strings.Compare(a[ka[i]], b[kb[i]])
263			}
264		}
265		switch {
266		case len(ka) < len(kb):
267			return -1
268		case len(ka) > len(kb):
269			return 1
270		default:
271			return 0
272		}
273	}
274	
275	func sortedKeys(m map[string]string) []string {
276		keys := make([]string, 0, len(m))
277		for k := range m {
278			keys = append(keys, k)
279		}
280		sort.Strings(keys)
281		return keys
282	}
283	
284	func copyLabels(in map[string]string) map[string]string {
285		out := make(map[string]string, len(in))
286		for k, v := range in {
287			out[k] = v
288		}
289		return out
290	}
291	
292	// seriesKey builds a collision-free identity from name + unordered labels.
293	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
294	// so length-prefixed values remove any ambiguity from arbitrary label values.
295	func seriesKey(name string, labels map[string]string) string {
296		var b strings.Builder
297		b.WriteString(name)
298		for _, k := range sortedKeys(labels) {
299			b.WriteByte(0)
300			b.WriteString(k)
301			b.WriteByte(0)
302			v := labels[k]
303			b.WriteString(strconv.Itoa(len(v)))
304			b.WriteByte(0)
305			b.WriteString(v)
306		}
307		return b.String()
308	}
309	
310	func equalBuckets(a, b []float64) bool {
311		if len(a) != len(b) {
312			return false
313		}
314		for i := range a {
315			if a[i] != b[i] {
316				return false
317			}
318		}
319		return true
320	}
321	
322	// Handler returns the HTTP surface served by SignalWatch.
323	func Handler() http.Handler {
324		return newHandler(newTenantRegistry())
325	}
326	
327	func newHandler(registry *tenantRegistry) http.Handler {
328		mux := http.NewServeMux()
329	
330		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
331			if r.Method != http.MethodGet {
332				w.Header().Set("Allow", http.MethodGet)
333				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
334				return
335			}
336			w.Header().Set("Content-Type", "application/json; charset=utf-8")
337			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
338		})
339	
340		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
341			switch r.Method {
342			case http.MethodGet:
343				handleMetricsGet(w, r)
344			case http.MethodPost:
345				handleMetricsPost(w, r)
346			default:
347				w.Header().Set("Allow", "GET, POST")
348				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
349			}
350		})
351	
352		registerAlertHandlers(mux)
353		registerSilenceHandlers(mux)
354		registerInhibitHandlers(mux)
355		registerNotificationRouteHandlers(mux)
356		registerSLOHandlers(mux)
357		registerQueryHandler(mux)
358		registerMetricRangeHandler(mux)
359		registerLogHandlers(mux)
360		registerSpanHandlers(mux)
361	
362		return withTenants(mux, registry)
363	}
364	
365	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
366		// All samples in the request share this single receive instant: it is the
367		// default timestamp and the anchor for the accepted timestamp window.
368		receivedAt := time.Now()
369		store := tenantStore(r)
370		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
371		if err != nil || mediaType != "application/json" {
372			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
373			return
374		}
375	
376		body, err := io.ReadAll(r.Body)
377		if err != nil {
378			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
379			return
380		}
381	
382		batch, code := decodeMetricsBatch(body, receivedAt)
383		if code != "" {
384			writeAPIError(w, code, http.StatusBadRequest)
385			return
386		}
387	
388		if !store.checkAndApply(batch) {
389			writeAPIError(w, "metric_conflict", http.StatusConflict)
390			return
391		}
392	
393		w.Header().Set("Content-Type", "application/json; charset=utf-8")
394		w.WriteHeader(http.StatusAccepted)
395		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
396	}
397	
398	type metricsEnvelope struct {
399		Samples *[]json.RawMessage `json:"samples"`
400	}
401	
402	type rawSample struct {
403		Name      *string            `json:"name"`
404		Type      *string            `json:"type"`
405		Labels    *map[string]string `json:"labels"`
406		Value     *float64           `json:"value"`
407		Buckets   *[]float64         `json:"buckets"`
408		Timestamp *string            `json:"timestamp"`
409	}
410	
411	// decodeMetricsBatch performs every format and value check, including the
412	// optional per-sample timestamp. It never returns a partially validated
413	// batch. The returned error code is empty on success.
414	func decodeMetricsBatch(body []byte, receivedAt time.Time) ([]validatedSample, string) {
415		var env metricsEnvelope
416		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
417			return nil, "invalid_metrics"
418		}
419	
420		batch := make([]validatedSample, 0, len(*env.Samples))
421		for _, raw := range *env.Samples {
422			var sm rawSample
423			if !strictDecode(raw, &sm) {
424				return nil, "invalid_metrics"
425			}
426			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
427				return nil, "invalid_metrics"
428			}
429			name, typ := *sm.Name, *sm.Type
430			if !identPattern.MatchString(name) {
431				return nil, "invalid_metrics"
432			}
433			if typ != "counter" && typ != "gauge" && typ != "histogram" {
434				return nil, "invalid_metrics"
435			}
436			labels := *sm.Labels
437			if labels == nil {
438				return nil, "invalid_metrics" // explicit null labels
439			}
440			for k := range labels {
441				if !identPattern.MatchString(k) {
442					return nil, "invalid_metrics"
443				}
444			}
445			value := *sm.Value
446			if math.IsNaN(value) || math.IsInf(value, 0) {
447				return nil, "invalid_metrics" // encoding/json already rejects NaN/Inf tokens
448			}
449			if typ == "counter" && value < 0 {
450				return nil, "invalid_metrics"
451			}
452	
453			var buckets []float64
454			if typ == "histogram" {
455				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
456					return nil, "invalid_metrics"
457				}
458				buckets = append([]float64(nil), (*sm.Buckets)...)
459			} else if sm.Buckets != nil {
460				return nil, "invalid_metrics" // buckets only valid on histograms
461			}
462	
463			// The timestamp is optional; every sample without one shares the
464			// request's receive instant.
465			ts := receivedAt
466			if sm.Timestamp != nil {
467				parsed, err := time.Parse(time.RFC3339Nano, *sm.Timestamp)
468				if err != nil {
469					return nil, "invalid_metrics"
470				}
471				ts = parsed
472			}
473			if ts.Before(receivedAt.Add(-metricRetention)) || ts.After(receivedAt.Add(maxFutureSkew)) {
474				return nil, "metric_timestamp_out_of_range"
475			}
476	
477			batch = append(batch, validatedSample{
478				key:     seriesKey(name, labels),
479				name:    name,
480				typ:     typ,
481				labels:  copyLabels(labels),
482				value:   value,
483				buckets: buckets,
484				ts:      ts,
485			})
486		}
487		return batch, ""
488	}
489	
490	func validBuckets(buckets []float64) bool {
491		if len(buckets) == 0 {
492			return false
493		}
494		prev := math.Inf(-1)
495		for _, b := range buckets {
496			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
497				return false
498			}
499			prev = b
500		}
501		return true
502	}
503	
504	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
505	// values and non-object payloads for struct targets.
506	func strictDecode(data []byte, target any) bool {
507		dec := json.NewDecoder(bytes.NewReader(data))
508		dec.DisallowUnknownFields()
509		if err := dec.Decode(target); err != nil {
510			return false
511		}
512		var extra json.RawMessage
513		if err := dec.Decode(&extra); err != io.EOF {
514			return false
515		}
516		return true
517	}
518	
519	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
520		store := tenantStore(r)
521		values, err := url.ParseQuery(r.URL.RawQuery)
522		if err != nil {
523			writeAPIError(w, "invalid_query", http.StatusBadRequest)
524			return
525		}
526	
527		names := values["name"]
528		if len(names) == 0 || !identPattern.MatchString(names[0]) {
529			writeAPIError(w, "invalid_query", http.StatusBadRequest)
530			return
531		}
532	
533		selector := make(map[string]string)
534		for key, vals := range values {
535			if !strings.HasPrefix(key, "label.") {
536				continue
537			}
538			labelKey := strings.TrimPrefix(key, "label.")
539			if !identPattern.MatchString(labelKey) {
540				writeAPIError(w, "invalid_query", http.StatusBadRequest)
541				return
542			}
543			for _, v := range vals[1:] {
544				if v != vals[0] {
545					writeAPIError(w, "invalid_query", http.StatusBadRequest)
546					return
547				}
548			}
549			selector[labelKey] = vals[0]
550		}
551	
552		seriesList := store.query(names[0], selector)
553		w.Header().Set("Content-Type", "application/json; charset=utf-8")
554		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
555	}
556	
557	func writeAPIError(w http.ResponseWriter, code string, status int) {
558		w.Header().Set("Content-Type", "application/json; charset=utf-8")
559		w.WriteHeader(status)
560		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
561	}
