195		for _, body := range badFormat {
196			expectErrorCode(t, postMetrics(t, h, body, ""), http.StatusBadRequest, "invalid_metrics")
197		}
198	
199		tooOld := time.Now().Add(-24*time.Hour - time.Minute).UTC().Format(time.RFC3339Nano)
200		tooNew := time.Now().Add(5*time.Minute + time.Minute).UTC().Format(time.RFC3339Nano)
201		for _, stamp := range []string{tooOld, tooNew} {
202			body := fmt.Sprintf(`{"samples":[{"name":"m","type":"gauge","labels":{},"value":1,"timestamp":%q}]}`, stamp)
203			expectErrorCode(t, postMetrics(t, h, body, ""), http.StatusBadRequest, "metric_timestamp_out_of_range")
204		}
