206		// A batch with one out-of-range sample commits nothing: no current value,
207		// no history.
208		good := time.Now().UTC().Format(time.RFC3339Nano)
209		body := fmt.Sprintf(`{"samples":[
210			{"name":"atomic","type":"counter","labels":{},"value":5,"timestamp":%q},
211			{"name":"atomic","type":"counter","labels":{},"value":5,"timestamp":%q}
212		]}`, good, tooOld)
213		expectErrorCode(t, postMetrics(t, h, body, ""), http.StatusBadRequest, "metric_timestamp_out_of_range")
214		rec := getMetrics(t, h, metricsPath+"?name=atomic")
