			if a == nil {
				a = &groupAgg{sum: v, min: v, max: v, count: 1}
				g.windows[k] = a
				continue
			}
			a.count++
			a.sum += v
			if v < a.min {
				a.min = v
			}
			if v > a.max {
				a.max = v
			}
		}
	}

