// non-finite, in which case no partial result is returned.
func (s *metricStore) executeQueryRange(e *queryExpr, start, end time.Time, step time.Duration, nWindows int, now time.Time) ([]matrixSeries, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

