		expr, ok := parseQueryExpr(exprRaw)
		if !ok {
			writeAPIError(w, "invalid_expression", http.StatusBadRequest)
			return
		}

		start, err := time.Parse(time.RFC3339Nano, startRaw)
		if err != nil {
			invalidRange()
			return
		}
		end, err := time.Parse(time.RFC3339Nano, endRaw)
		if err != nil {
			invalidRange()
			return
		}
