1	package server
2	
3	import (
4		"math"
5		"net/http"
6		"net/url"
7		"sort"
8		"time"
9	)
10	
11	const queryRangePath = "/api/v1/query-range"
12	
13	// matrixPoint is one window value of a result series.
14	type matrixPoint struct {
15		Timestamp string  `json:"timestamp"`
16		Value     float64 `json:"value"`
17	}
18	
19	type matrixSeries struct {
20		Labels map[string]string `json:"labels"`
21		Points []matrixPoint     `json:"points"`
22	}
23	
24	type matrixResponse struct {
25		ResultType string         `json:"result_type"`
26		Result     []matrixSeries `json:"result"`
27	}
28	
29	// seriesWindowValues computes the per-window values of one counter/gauge
30	// series over the half-open windows cut from start. Histograms never
31	// participate. A window without a retained sample is absent from the map.
32	// ok is false when a counter window sum is not a finite number.
33	func seriesWindowValues(cur *series, start, end, cutoff time.Time, step time.Duration) (map[int]float64, bool) {
34		inRange := func(ts time.Time) bool {
35			return !ts.Before(cutoff) && !ts.Before(start) && ts.Before(end)
36		}
37		windowOf := func(ts time.Time) int {
38			return int(ts.Sub(start) / step)
39		}
40	
41		switch cur.typ {
42		case "counter":
43			sums := make(map[int]float64)
44			for _, p := range cur.history {
45				if inRange(p.ts) {
46					sums[windowOf(p.ts)] += p.value
47				}
48			}
49			for _, v := range sums {
50				if math.IsNaN(v) || math.IsInf(v, 0) {
51					return nil, false
52				}
53			}
54			return sums, true
55	
56		case "gauge":
57			// history is commit order, so a strictly later iteration position on
58			// equal timestamps wins; track the winning index explicitly.
59			type pick struct {
60				value float64
61				ts    time.Time
62				idx   int
63			}
64			best := make(map[int]pick)
65			for i, p := range cur.history {
66				if !inRange(p.ts) {
67					continue
68				}
69				k := windowOf(p.ts)
70				if b, ok := best[k]; !ok || p.ts.After(b.ts) || (p.ts.Equal(b.ts) && i > b.idx) {
71					best[k] = pick{value: p.value, ts: p.ts, idx: i}
72				}
73			}
74			out := make(map[int]float64, len(best))
75			for k, b := range best {
76				out[k] = b.value
77			}
78			return out, true
79		}
80		return nil, true
81	}
82	
83	// executeQueryRange evaluates a parsed expression per fixed window against a
84	// single consistent store snapshot. Only counter and gauge series
85	// participate; histograms are ignored. Aggregations fold only the series
86	// that have a value in that window, and a group absent in a window emits no
87	// point. The third result is false when any window value or aggregate is
88	// non-finite, in which case no partial result is returned.
89	func (s *metricStore) executeQueryRange(e *queryExpr, start, end time.Time, step time.Duration, nWindows int, now time.Time) ([]matrixSeries, bool) {
90		s.mu.RLock()
91		defer s.mu.RUnlock()
92	
93		cutoff := now.Add(-metricRetention)
94	
95		type matched struct {
96			labels map[string]string
97			values map[int]float64
98		}
99		all := make([]matched, 0)
100		for _, cur := range s.series {
101			if cur.typ != "counter" && cur.typ != "gauge" {
102				continue
103			}
104			if cur.name != e.metric {
105				continue
106			}
107			fits := true
108			for k, v := range e.selector {
109				got, ok := cur.labels[k]
110				if !ok || got != v {
111					fits = false
112					break
113				}
114			}
115			if !fits {
116				continue
117			}
118			values, finite := seriesWindowValues(cur, start, end, cutoff, step)
119			if !finite {
120				return nil, false
121			}
122			all = append(all, matched{labels: copyLabels(cur.labels), values: values})
123		}
124	
125		windowStamps := make([]string, nWindows)
126		for k := 0; k < nWindows; k++ {
127			windowStamps[k] = start.Add(time.Duration(k) * step).UTC().Format(time.RFC3339Nano)
128		}
129	
130		if e.aggregate == "" {
131			pointsOf := func(perWindow map[int]float64) []matrixPoint {
132				keys := make([]int, 0, len(perWindow))
133				for k := range perWindow {
134					keys = append(keys, k)
135				}
136				sort.Ints(keys)
137				points := make([]matrixPoint, 0, len(keys))
138				for _, k := range keys {
139					points = append(points, matrixPoint{Timestamp: windowStamps[k], Value: perWindow[k]})
140				}
141				return points
142			}
143			// Sort matched series by full labels once; their points are already
144			// ascending by construction. Series without any point are omitted.
145			sort.Slice(all, func(i, j int) bool {
146				return compareLabels(all[i].labels, all[j].labels) < 0
147			})
148			out := make([]matrixSeries, 0, len(all))
149			for _, m := range all {
150				if len(m.values) == 0 {
151					continue
152				}
153				out = append(out, matrixSeries{Labels: m.labels, Points: pointsOf(m.values)})
154			}
155			return out, true
156		}
157	
158		// Aggregations: group by projected labels per window. A group exists in a
159		// window only when at least one series has a value there.
160		type groupAgg struct {
161			sum   float64
162			min   float64
163			max   float64
164			count int
165		}
166		type groupState struct {
167			labels map[string]string
168			// indexed by window; nil entries are empty windows.
169			windows []*groupAgg
170		}
171		groups := make(map[string]*groupState)
172		groupOrder := make([]string, 0)
173	
174		for _, m := range all {
175			projected := make(map[string]string, len(e.by))
176			for _, label := range e.by {
177				if v, ok := m.labels[label]; ok {
178					projected[label] = v
179				}
180			}
181			key := seriesKey("", projected)
182			g, seen := groups[key]
183			if !seen {
184				g = &groupState{labels: projected, windows: make([]*groupAgg, nWindows)}
185				groups[key] = g
186				groupOrder = append(groupOrder, key)
187			}
188			for k, v := range m.values {
189				a := g.windows[k]
190				if a == nil {
191					a = &groupAgg{sum: v, min: v, max: v, count: 1}
192					g.windows[k] = a
193					continue
194				}
195				a.count++
196				a.sum += v
197				if v < a.min {
198					a.min = v
199				}
200				if v > a.max {
201					a.max = v
202				}
203			}
204		}
205	
206		out := make([]matrixSeries, 0, len(groupOrder))
207		for _, key := range groupOrder {
208			g := groups[key]
209			points := make([]matrixPoint, 0)
210			for k, a := range g.windows {
211				if a == nil {
212					continue // no series had a value in this window; never zero-fill
213				}
214				var v float64
215				switch e.aggregate {
216				case "sum":
217					v = a.sum
218				case "avg":
219					v = a.sum / float64(a.count)
220				case "min":
221					v = a.min
222				case "max":
223					v = a.max
224				}
225				if math.IsNaN(v) || math.IsInf(v, 0) {
226					return nil, false
227				}
228				points = append(points, matrixPoint{Timestamp: windowStamps[k], Value: v})
229			}
230			if len(points) > 0 {
231				out = append(out, matrixSeries{Labels: g.labels, Points: points})
232			}
233		}
234		sort.Slice(out, func(i, j int) bool {
235			return compareLabels(out[i].Labels, out[j].Labels) < 0
236		})
237		return out, true
238	}
239	
240	// ---- HTTP handler ----------------------------------------------------------
241	
242	func registerQueryRangeHandler(mux *http.ServeMux) {
243		mux.HandleFunc(queryRangePath, func(w http.ResponseWriter, r *http.Request) {
244			if r.Method != http.MethodGet {
245				w.Header().Set("Allow", http.MethodGet)
246				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
247				return
248			}
249			invalidRange := func() {
250				writeAPIError(w, "invalid_query_range", http.StatusBadRequest)
